CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('admin','manager','technician','approver','faculty','student')));
CREATE TABLE IF NOT EXISTS facilities (id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, restricted BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS bookings (id SERIAL PRIMARY KEY, request_key TEXT UNIQUE, facility_id INT NOT NULL REFERENCES facilities(id), user_id INT NOT NULL REFERENCES users(id), starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, status TEXT NOT NULL CHECK(status IN ('requested','approved','confirmed','in_use','completed','cancelled')), purpose TEXT NOT NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(ends_at > starts_at));
DO $$ BEGIN ALTER TABLE bookings ADD CONSTRAINT bookings_no_overlap EXCLUDE USING gist (facility_id WITH =, tstzrange(starts_at, ends_at, '[)') WITH &&) WHERE (status IN ('approved','confirmed','in_use')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS sla_policies (priority TEXT PRIMARY KEY, response_minutes INT NOT NULL, resolution_minutes INT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets (id SERIAL PRIMARY KEY, source_key TEXT UNIQUE, facility_id INT REFERENCES facilities(id), booking_id INT REFERENCES bookings(id), title TEXT NOT NULL, category TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('low','medium','high','critical')), status TEXT NOT NULL CHECK(status IN ('intake','assigned','inspection','pending_work','resolved','closed')), assignee_id INT REFERENCES users(id), notes TEXT NOT NULL DEFAULT '', version INT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sensor_alerts (id SERIAL PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, facility_id INT NOT NULL REFERENCES facilities(id), reading NUMERIC NOT NULL, threshold NUMERIC NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), ticket_id INT REFERENCES tickets(id));
CREATE TABLE IF NOT EXISTS approvals (id SERIAL PRIMARY KEY, booking_id INT REFERENCES bookings(id), ticket_id INT REFERENCES tickets(id), approver_id INT NOT NULL REFERENCES users(id), decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')), reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((booking_id IS NULL) <> (ticket_id IS NULL)));
CREATE TABLE IF NOT EXISTS integration_links (id SERIAL PRIMARY KEY, object_type TEXT NOT NULL, object_id INT NOT NULL, external_key TEXT NOT NULL UNIQUE, mode TEXT NOT NULL CHECK(mode IN ('simulated_local')), state TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id BIGSERIAL PRIMARY KEY, actor_id INT REFERENCES users(id), object_type TEXT NOT NULL, object_id INT NOT NULL, action TEXT NOT NULL, detail JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
